#[test]
fn test_unread_ink_keeps_source_page_and_box_without_invented_text() {
    let lines: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let inks: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mask: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    oi_line(lines, 1, 800);
    ik_new(inks, 1, 0);
    ik_set(inks, 0, ikf_role(), ir_body());
    crate::port::cells_push(mask, 1);
    crate::testport::assert_eq(oc_ink_account(lines, inks, &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), mask, ledger, &mut crate::port::Cells::new(), &mut crate::port::Cells::new()), 1, "source region has no recorded reading");
    crate::testport::assert_eq(ledger_count(ledger), 1, "one region, not a guessed word count");
    crate::testport::assert_eq(ledger_reason(ledger, 0), dr_ocr_unread_ink(), "distinct from rejected OCR alternatives");
    crate::testport::assert_eq(ledger_page(ledger, 0), 1, "source page owns the diagnostic");
    crate::testport::assert_eq(ledger_x0(ledger, 0), 1000, "source left");
    crate::testport::assert_eq(ledger_y0(ledger, 0), 2000, "source top");
    crate::testport::assert_eq(ledger_x1(ledger, 0), 5000, "source right");
    crate::testport::assert_eq(ledger_y1(ledger, 0), 2500, "source bottom");
    crate::testport::assert_eq(ledger_text_len(ledger, 0), 0, "pixels supply no invented transcription");
    crate::testport::assert_eq(ledger_conf(ledger, 0), -1, "trace confidence is not a calibrated OCR word confidence");
}
